SELECT
    (SELECT [M].[Month] FROM (VALUES (MAX([T].[PostingDate]))) AS [V1] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V1].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V1].[v] < [M].[EndDate]) AS [c0],
    (SELECT (SELECT [M2].[StartDate] FROM [core].[CalendarMonths] AS [M2] WHERE [M2].[Calendar] = @qx0_p0 AND [M2].[Year] = [M].[Year] AND [M2].[Month] = 1) FROM (VALUES (MIN([T].[PostingDate]))) AS [V1] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V1].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V1].[v] < [M].[EndDate]) AS [c1],
    (SELECT (SELECT ((([M2].[Year] * 12 + [M2].[Month]) - ([M].[Year] * 12 + [M].[Month])) + CASE WHEN (([M2].[Year] * 12 + [M2].[Month]) - ([M].[Year] * 12 + [M].[Month])) > 0 AND DATEADD(DAY, DATEDIFF(DAY, [M].[StartDate], [M2].[StartDate]) + LEAST(0, DATEDIFF(DAY, [M2].[StartDate], [M2].[EndDate]) - 1 - DATEDIFF(DAY, [M].[StartDate], [V2].[v])), [V2].[v]) > [V1].[v] THEN -1 WHEN (([M2].[Year] * 12 + [M2].[Month]) - ([M].[Year] * 12 + [M].[Month])) < 0 AND DATEADD(DAY, DATEDIFF(DAY, [M].[StartDate], [M2].[StartDate]) + LEAST(0, DATEDIFF(DAY, [M2].[StartDate], [M2].[EndDate]) - 1 - DATEDIFF(DAY, [M].[StartDate], [V2].[v])), [V2].[v]) < [V1].[v] THEN 1 ELSE 0 END) FROM (VALUES (MAX([T].[PostingDate]))) AS [V1] ([v]) CROSS APPLY (SELECT TOP (1) [M2].[Year], [M2].[Month], [M2].[StartDate], [M2].[EndDate] FROM [core].[CalendarMonths] AS [M2] WHERE [M2].[Calendar] = @qx0_p0 AND [M2].[StartDate] <= [V1].[v] ORDER BY [M2].[StartDate] DESC) AS [M2] WHERE [V1].[v] < [M2].[EndDate]) FROM (VALUES (MIN([T].[PostingDate]))) AS [V2] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V2].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V2].[v] < [M].[EndDate]) AS [c2],
    (SELECT (SELECT DATEADD(DAY, DATEDIFF(DAY, [M].[StartDate], [M2].[StartDate]) + LEAST(0, DATEDIFF(DAY, [M2].[StartDate], [M2].[EndDate]) - 1 - DATEDIFF(DAY, [M].[StartDate], [V2].[v])), [V1].[v]) FROM [core].[CalendarMonths] AS [M2] WHERE [M2].[Calendar] = @qx0_p0 AND [M2].[Year] = (([M].[Year] * 12 + [M].[Month] - 1 + CAST(@qx0_p1 AS int)) / 12) AND [M2].[Month] = (([M].[Year] * 12 + [M].[Month] - 1 + CAST(@qx0_p1 AS int)) % 12 + 1)) FROM (VALUES (MAX([T].[PostedOn]))) AS [V1] ([v]) CROSS APPLY (VALUES (CAST([V1].[v] AS date))) AS [V2] ([v]) CROSS APPLY (SELECT TOP (1) [M].[Year], [M].[Month], [M].[StartDate], [M].[EndDate] FROM [core].[CalendarMonths] AS [M] WHERE [M].[Calendar] = @qx0_p0 AND [M].[StartDate] <= [V2].[v] ORDER BY [M].[StartDate] DESC) AS [M] WHERE [V2].[v] < [M].[EndDate]) AS [c3]
FROM [gl].[Documents] AS [T]
;

-- parameters
--   @qx0_p0 : QxString QxVarChar(8000) Literal = 'uq'
--   @qx0_p1 : QxNumeric QxDecimal(1, 0) Literal = 1
-- columns
--   0 : QxNumeric Nullable month(max(PostingDate), 'uq')
--   1 : QxDate Nullable startOfYear(min(PostingDate), 'uq')
--   2 : QxNumeric Nullable diffMonths(min(PostingDate), max(PostingDate), 'uq')
--   3 : QxDateTime Nullable addMonths(max(PostedOn), 1, 'uq')
